@page "/apply"
@using sv_055b1fe4583542c385bf765b72e3a444.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4">
    <h2 class="mb-4">Job Application</h2>

    @if (!_submitted)
    {
        <StepIndicator CurrentStep="_currentStep"
                       CompletedSteps="_completedSteps"
                       OnStepClicked="GoToStep" />

        <div class="card mt-4">
            <div class="card-body">
                @switch (_currentStep)
                {
                    case 1:
                        <StepPersonalInfo FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                                          FullNameChanged="v => _fullName = v"
                                          EmailChanged="v => _email = v"
                                          PhoneChanged="v => _phone = v"
                                          AddressChanged="v => _address = v"
                                          ValidationError="@_validationError" />
                        break;
                    case 2:
                        <StepWorkHistory WorkEntries="_workEntries"
                                         IsCurrent="_isCurrentJob"
                                         OnAddEntry="AddWorkEntry"
                                         OnRemoveEntry="RemoveWorkEntry"
                                         OnToggleCurrent="ToggleCurrentJob"
                                         ValidationError="@_validationError" />
                        break;
                    case 3:
                        <StepReferences References="_references"
                                        OnAddReference="AddReference"
                                        OnRemoveReference="RemoveReference"
                                        ValidationError="@_validationError" />
                        break;
                    case 4:
                        <StepCoverLetter CoverLetter="@_coverLetter"
                                         CoverLetterChanged="v => _coverLetter = v"
                                         MaxLength="2000"
                                         ValidationError="@_validationError" />
                        break;
                    case 5:
                        <StepReview FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                                    WorkEntries="_workEntries" IsCurrent="_isCurrentJob"
                                    References="_references" CoverLetter="@_coverLetter"
                                    OnEditSection="GoToStep"
                                    IsSubmitting="_isSubmitting"
                                    SubmitError="@_submitError" />
                        break;
                }
            </div>
            <div class="card-footer d-flex justify-content-between">
                @if (_currentStep > 1)
                {
                    <button class="btn btn-outline-secondary" @onclick="PreviousStep" disabled="@_isProcessing">
                        &larr; Back
                    </button>
                }
                else
                {
                    <span></span>
                }

                @if (_currentStep < 5)
                {
                    <button class="btn btn-primary" @onclick="NextStep" disabled="@_isProcessing">
                        @if (_isProcessing)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                        }
                        Next &rarr;
                    </button>
                }
                else
                {
                    <button class="btn btn-success" @onclick="Submit" disabled="@_isSubmitting">
                        @if (_isSubmitting)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                            <text>Submitting...</text>
                        }
                        else
                        {
                            <text>Submit Application</text>
                        }
                    </button>
                }
            </div>
        </div>
    }
    else
    {
        <div class="card mt-4">
            <div class="card-body text-center py-5">
                <div class="mb-3">
                    <span class="text-success" style="font-size:4rem;">&#10003;</span>
                </div>
                <h3 class="text-success">Application Submitted!</h3>
                <p class="lead mt-3">Your application has been received.</p>
                <p class="fs-5">Application ID: <strong>@_applicationId</strong></p>
                <a href="/apply" class="btn btn-primary mt-3">Submit Another Application</a>
            </div>
        </div>
    }
</div>

@code {
    private int _currentStep = 1;
    private HashSet<int> _completedSteps = new();
    private string? _validationError;
    private string? _submitError;
    private bool _isProcessing;
    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;

    // Step 1 — Personal Info
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 — Work History
    private List<WorkEntryModel> _workEntries = new() { new() };
    private List<bool> _isCurrentJob = new() { false };

    // Step 3 — References
    private List<ReferenceModel> _references = new() { new(), new() };

    // Step 4 — Cover Letter
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        if (step <= _currentStep || _completedSteps.Contains(step))
        {
            _validationError = null;
            _currentStep = step;
        }
    }

    private async Task NextStep()
    {
        _validationError = null;
        _isProcessing = true;

        try
        {
            if (!ValidateCurrentStep())
                return;

            if (_currentStep == 1)
            {
                var emailValid = await ApplicationService.ValidateEmailAsync(_email);
                if (!emailValid)
                {
                    _validationError = "Please enter a valid email address.";
                    return;
                }
            }

            _completedSteps.Add(_currentStep);
            _currentStep++;
        }
        finally
        {
            _isProcessing = false;
        }
    }

    private void PreviousStep()
    {
        _validationError = null;
        if (_currentStep > 1)
            _currentStep--;
    }

    private bool ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 1:
                if (string.IsNullOrWhiteSpace(_fullName))
                    { _validationError = "Full name is required."; return false; }
                if (string.IsNullOrWhiteSpace(_email))
                    { _validationError = "Email is required."; return false; }
                if (string.IsNullOrWhiteSpace(_phone))
                    { _validationError = "Phone number is required."; return false; }
                if (string.IsNullOrWhiteSpace(_address))
                    { _validationError = "Address is required."; return false; }
                return true;
            case 2:
                foreach (var entry in _workEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company))
                        { _validationError = "Company name is required for all entries."; return false; }
                    if (string.IsNullOrWhiteSpace(entry.Title))
                        { _validationError = "Job title is required for all entries."; return false; }
                    if (entry.StartDate == default)
                        { _validationError = "Start date is required for all entries."; return false; }
                }
                return true;
            case 3:
                if (_references.Count == 0)
                    { _validationError = "At least one reference is required."; return false; }
                foreach (var r in _references)
                {
                    if (string.IsNullOrWhiteSpace(r.Name))
                        { _validationError = "Name is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(r.Email))
                        { _validationError = "Email is required for all references."; return false; }
                }
                return true;
            case 4:
                if (string.IsNullOrWhiteSpace(_coverLetter))
                    { _validationError = "Cover letter is required."; return false; }
                if (_coverLetter.Length > 2000)
                    { _validationError = "Cover letter must be 2000 characters or fewer."; return false; }
                return true;
            default:
                return true;
        }
    }

    private void AddWorkEntry()
    {
        _workEntries.Add(new());
        _isCurrentJob.Add(false);
    }

    private void RemoveWorkEntry(int index)
    {
        if (_workEntries.Count > 1)
        {
            _workEntries.RemoveAt(index);
            _isCurrentJob.RemoveAt(index);
        }
    }

    private void ToggleCurrentJob(int index)
    {
        _isCurrentJob[index] = !_isCurrentJob[index];
        if (_isCurrentJob[index])
            _workEntries[index].EndDate = null;
    }

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 1)
            _references.RemoveAt(index);
    }

    private async Task Submit()
    {
        _submitError = null;
        _isSubmitting = true;

        try
        {
            var workEntries = _workEntries.Select((e, i) => new Models.WorkEntry(
                e.Company, e.Title, e.StartDate,
                _isCurrentJob[i] ? null : e.EndDate,
                e.Description ?? ""
            )).ToList();

            var refs = _references.Select(r => new Models.Reference(
                r.Name, r.Relationship ?? "", r.Email, r.Phone ?? ""
            )).ToList();

            var application = new Models.JobApplication(
                new Models.PersonalInfo(_fullName, _email, _phone, _address),
                new Models.WorkHistory(workEntries),
                refs,
                _coverLetter
            );

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public string? Description { get; set; } = "";
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@{
    var steps = new[] { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
}

<nav aria-label="Application steps">
    <ol class="d-flex list-unstyled mb-0 step-indicator">
        @for (int i = 0; i < steps.Length; i++)
        {
            var stepNum = i + 1;
            var isCompleted = CompletedSteps.Contains(stepNum);
            var isCurrent = stepNum == CurrentStep;
            var isClickable = isCompleted && !isCurrent;

            <li class="flex-fill text-center position-relative @(isCurrent ? "step-current" : isCompleted ? "step-completed" : "step-future")">
                @if (isClickable)
                {
                    <a href="javascript:void(0)" @onclick="() => OnStepClicked.InvokeAsync(stepNum)"
                       class="text-decoration-none d-block py-2">
                        <span class="step-circle">&#10003;</span>
                        <span class="d-block small mt-1">@steps[i]</span>
                    </a>
                }
                else
                {
                    <div class="py-2">
                        <span class="step-circle">
                            @if (isCompleted)
                            {
                                <text>&#10003;</text>
                            }
                            else
                            {
                                @stepNum
                            }
                        </span>
                        <span class="d-block small mt-1">@steps[i]</span>
                    </div>
                }
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

.step-indicator {
    counter-reset: step;
}

.step-indicator li {
    padding: 0 0.5rem;
}

.step-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    font-weight: bold;
    font-size: 0.85rem;
}

.step-current .step-circle {
    background-color: #0d6efd;
    color: white;
}

.step-current span {
    color: #0d6efd;
    font-weight: 600;
}

.step-completed .step-circle {
    background-color: #198754;
    color: white;
}

.step-completed a {
    color: #198754;
}

.step-future .step-circle {
    background-color: #dee2e6;
    color: #6c757d;
}

.step-future span {
    color: #adb5bd;
}

