@page "/apply"
@using sv_055b1fe4583542c385bf765b72e3a444.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4">
    <h2 class="mb-4">Job Application</h2>

    @if (!_submitted)
    {
        <StepIndicator CurrentStep="_currentStep"
                       CompletedSteps="_completedSteps"
                       OnStepClicked="GoToStep" />

        <div class="card mt-4">
            <div class="card-body">
                @switch (_currentStep)
                {
                    case 1:
                        <StepPersonalInfo FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                                          FullNameChanged="v => _fullName = v"
                                          EmailChanged="v => _email = v"
                                          PhoneChanged="v => _phone = v"
                                          AddressChanged="v => _address = v"
                                          ValidationError="@_validationError" />
                        break;
                    case 2:
                        <StepWorkHistory WorkEntries="_workEntries"
                                         IsCurrent="_isCurrentJob"
                                         OnAddEntry="AddWorkEntry"
                                         OnRemoveEntry="RemoveWorkEntry"
                                         OnToggleCurrent="ToggleCurrentJob"
                                         ValidationError="@_validationError" />
                        break;
                    case 3:
                        <StepReferences References="_references"
                                        OnAddReference="AddReference"
                                        OnRemoveReference="RemoveReference"
                                        ValidationError="@_validationError" />
                        break;
                    case 4:
                        <StepCoverLetter CoverLetter="@_coverLetter"
                                         CoverLetterChanged="v => _coverLetter = v"
                                         MaxLength="2000"
                                         ValidationError="@_validationError" />
                        break;
                    case 5:
                        <StepReview FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                                    WorkEntries="_workEntries" IsCurrent="_isCurrentJob"
                                    References="_references" CoverLetter="@_coverLetter"
                                    OnEditSection="GoToStep"
                                    IsSubmitting="_isSubmitting"
                                    SubmitError="@_submitError" />
                        break;
                }
            </div>
            <div class="card-footer d-flex justify-content-between">
                @if (_currentStep > 1)
                {
                    <button class="btn btn-outline-secondary" @onclick="PreviousStep" disabled="@_isProcessing">
                        &larr; Back
                    </button>
                }
                else
                {
                    <span></span>
                }

                @if (_currentStep < 5)
                {
                    <button class="btn btn-primary" @onclick="NextStep" disabled="@_isProcessing">
                        @if (_isProcessing)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                        }
                        Next &rarr;
                    </button>
                }
                else
                {
                    <button class="btn btn-success" @onclick="Submit" disabled="@_isSubmitting">
                        @if (_isSubmitting)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                            <text>Submitting...</text>
                        }
                        else
                        {
                            <text>Submit Application</text>
                        }
                    </button>
                }
            </div>
        </div>
    }
    else
    {
        <div class="card mt-4">
