            case 1:
                if (string.IsNullOrWhiteSpace(_fullName))
                    { _validationError = "Full name is required."; return false; }
                if (string.IsNullOrWhiteSpace(_email))
                    { _validationError = "Email is required."; return false; }
                if (string.IsNullOrWhiteSpace(_phone))
                    { _validationError = "Phone number is required."; return false; }
                if (string.IsNullOrWhiteSpace(_address))
                    { _validationError = "Address is required."; return false; }
                return true;
            case 2:
                foreach (var entry in _workEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company))
                        { _validationError = "Company name is required for all entries."; return false; }
                    if (string.IsNullOrWhiteSpace(entry.Title))
                        { _validationError = "Job title is required for all entries."; return false; }
                    if (entry.StartDate == default)
                        { _validationError = "Start date is required for all entries."; return false; }
                }
                return true;
            case 3:
                if (_references.Count == 0)
                    { _validationError = "At least one reference is required."; return false; }
                foreach (var r in _references)
                {
                    if (string.IsNullOrWhiteSpace(r.Name))
                        { _validationError = "Name is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(r.Email))
                        { _validationError = "Email is required for all references."; return false; }
                }
                return true;
            case 4:
                if (string.IsNullOrWhiteSpace(_coverLetter))
                    { _validationError = "Cover letter is required."; return false; }
                if (_coverLetter.Length > 2000)
                    { _validationError = "Cover letter must be 2000 characters or fewer."; return false; }
                return true;
            default:
                return true;
        }
    }

    private void AddWorkEntry()
    {
        _workEntries.Add(new());
        _isCurrentJob.Add(false);
    }

    private void RemoveWorkEntry(int index)
    {
        if (_workEntries.Count > 1)
        {
            _workEntries.RemoveAt(index);
            _isCurrentJob.RemoveAt(index);
        }
    }

    private void ToggleCurrentJob(int index)
    {
        _isCurrentJob[index] = !_isCurrentJob[index];
        if (_isCurrentJob[index])
            _workEntries[index].EndDate = null;
    }

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 1)
            _references.RemoveAt(index);
    }

    private async Task Submit()
    {
        _submitError = null;
        _isSubmitting = true;

        try
        {
            var workEntries = _workEntries.Select((e, i) => new Models.WorkEntry(
                e.Company, e.Title, e.StartDate,
                _isCurrentJob[i] ? null : e.EndDate,
                e.Description ?? ""
            )).ToList();

            var refs = _references.Select(r => new Models.Reference(
                r.Name, r.Relationship ?? "", r.Email, r.Phone ?? ""
            )).ToList();

            var application = new Models.JobApplication(
                new Models.PersonalInfo(_fullName, _email, _phone, _address),
                new Models.WorkHistory(workEntries),
                refs,
                _coverLetter
            );

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public string? Description { get; set; } = "";
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}
