@{
    var steps = new[] { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
}

<nav aria-label="Application steps">
    <ol class="d-flex list-unstyled mb-0 step-indicator">
        @for (int i = 0; i < steps.Length; i++)
        {
            var stepNum = i + 1;
            var isCompleted = CompletedSteps.Contains(stepNum);
            var isCurrent = stepNum == CurrentStep;
            var isClickable = isCompleted && !isCurrent;

            <li class="flex-fill text-center position-relative @(isCurrent ? "step-current" : isCompleted ? "step-completed" : "step-future")">
                @if (isClickable)
                {
                    <a href="javascript:void(0)" @onclick="() => OnStepClicked.InvokeAsync(stepNum)"
                       class="text-decoration-none d-block py-2">
                        <span class="step-circle">&#10003;</span>
                        <span class="d-block small mt-1">@steps[i]</span>
                    </a>
                }
                else
                {
                    <div class="py-2">
                        <span class="step-circle">
                            @if (isCompleted)
                            {
                                <text>&#10003;</text>
                            }
                            else
                            {
                                @stepNum
                            }
                        </span>
                        <span class="d-block small mt-1">@steps[i]</span>
                    </div>
                }
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

