toolArgs.file_text:
.step-indicator {
    counter-reset: step;
}

.step-indicator li {
    padding: 0 0.5rem;
}

.step-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    font-weight: bold;
    font-size: 0.85rem;
}

.step-current .step-circle {
    background-color: #0d6efd;
    color: white;
}

.step-current span {
    color: #0d6efd;
    font-weight: 600;
}

.step-completed .step-circle {
    background-color: #198754;
    color: white;
}

.step-completed a {
    color: #198754;
}

.step-future .step-circle {
    background-color: #dee2e6;
    color: #6c757d;
}

.step-future span {
    color: #adb5bd;
}

