toolArgs.file_text:
@using static sv_055b1fe4583542c385bf765b72e3a444.Components.Pages.Apply.Apply

<h4>Work History</h4>

@if (!string.IsNullOrEmpty(ValidationError))
{
    <div class="alert alert-danger">@ValidationError</div>
}

@for (int i = 0; i < WorkEntries.Count; i++)
{
    var index = i;
    var entry = WorkEntries[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Position @(index + 1)</h6>
                @if (WorkEntries.Count > 1)
                {
                    <button type="button" class="btn btn-sm btn-outline-danger"
                            @onclick="() => OnRemoveEntry.InvokeAsync(index)">Remove</button>
                }
            </div>

            <div class="row">
                <div class="col-md-6 mb-3">
                    <label class="form-label">Company <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" @bind="entry.Company" />
                </div>
                <div class="col-md-6 mb-3">
                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" @bind="entry.Title" />
                </div>
            </div>

            <div class="row">
                <div class="col-md-4 mb-3">
                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                    <input type="date" class="form-control" @bind="entry.StartDate" />
                </div>
                <div class="col-md-4 mb-3">
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control" @bind="entry.EndDate"
                           disabled="@IsCurrent[index]" />
                </div>
                <div class="col-md-4 mb-3 d-flex align-items-end">
                    <div class="form-check">
                        <input type="checkbox" class="form-check-input" id="current-@index"
                               checked="@IsCurrent[index]"
                               @onchange="() => OnToggleCurrent.InvokeAsync(index)" />
                        <label class="form-check-label" for="current-@index">Currently working here</label>
                    </div>
                </div>
            </div>

            <div class="mb-2">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" @bind="entry.Description"></textarea>
            </div>
        </div>
    </div>
}

<button type="button" class="btn btn-outline-primary" @onclick="OnAddEntry">
    + Add Another Position
</button>

@code {
    [Parameter] public List<WorkEntryModel> WorkEntries { get; set; } = new();
    [Parameter] public List<bool> IsCurrent { get; set; } = new();
    [Parameter] public EventCallback OnAddEntry { get; set; }
    [Parameter] public EventCallback<int> OnRemoveEntry { get; set; }
    [Parameter] public EventCallback<int> OnToggleCurrent { get; set; }
    [Parameter] public string? ValidationError { get; set; }
}

@using static sv_055b1fe4583542c385bf765b72e3a444.Components.Pages.Apply.Apply

<h4>References</h4>

@if (!string.IsNullOrEmpty(ValidationError))
{
    <div class="alert alert-danger">@ValidationError</div>
}

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    var reference = References[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Reference @(index + 1)</h6>
                @if (References.Count > 1)
                {
                    <button type="button" class="btn btn-sm btn-outline-danger"
                            @onclick="() => OnRemoveReference.InvokeAsync(index)">Remove</button>
                }
            </div>

            <div class="row">
                <div class="col-md-6 mb-3">
                    <label class="form-label">Name <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" @bind="reference.Name" />
                </div>
                <div class="col-md-6 mb-3">
                    <label class="form-label">Relationship</label>
                    <input type="text" class="form-control" @bind="reference.Relationship" />
                </div>
            </div>

            <div class="row">
                <div class="col-md-6 mb-3">
                    <label class="form-label">Email <span class="text-danger">*</span></label>
                    <input type="email" class="form-control" @bind="reference.Email" />
                </div>
                <div class="col-md-6 mb-3">
                    <label class="form-label">Phone</label>
                    <input type="tel" class="form-control" @bind="reference.Phone" />
                </div>
            </div>
        </div>
    </div>
}

@if (References.Count < 3)
{
    <button type="button" class="btn btn-outline-primary" @onclick="OnAddReference">
        + Add Reference
    </button>
}

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public EventCallback OnAddReference { get; set; }
    [Parameter] public EventCallback<int> OnRemoveReference { get; set; }
    [Parameter] public string? ValidationError { get; set; }
}

@using static sv_055b1fe4583542c385bf765b72e3a444.Components.Pages.Apply.Apply

<h4>Review &amp; Submit</h4>

@if (!string.IsNullOrEmpty(SubmitError))
{
    <div class="alert alert-danger">@SubmitError</div>
}

<!-- Personal Info -->
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Personal Information</strong>
        <a href="javascript:void(0)" @onclick='() => OnEditSection.InvokeAsync(1)'>Edit</a>
    </div>
    <div class="card-body">
        <dl class="row mb-0">
            <dt class="col-sm-3">Full Name</dt>
            <dd class="col-sm-9">@FullName</dd>
            <dt class="col-sm-3">Email</dt>
            <dd class="col-sm-9">@Email</dd>
            <dt class="col-sm-3">Phone</dt>
            <dd class="col-sm-9">@Phone</dd>
            <dt class="col-sm-3">Address</dt>
            <dd class="col-sm-9">@Address</dd>
        </dl>
    </div>
</div>

<!-- Work History -->
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Work History</strong>
        <a href="javascript:void(0)" @onclick='() => OnEditSection.InvokeAsync(2)'>Edit</a>
    </div>
    <div class="card-body">
        @for (int i = 0; i < WorkEntries.Count; i++)
        {
            var entry = WorkEntries[i];
            if (i > 0)
            {
                <hr />
            }
            <dl class="row mb-0">
                <dt class="col-sm-3">Company</dt>
                <dd class="col-sm-9">@entry.Company</dd>
                <dt class="col-sm-3">Title</dt>
                <dd class="col-sm-9">@entry.Title</dd>
                <dt class="col-sm-3">Period</dt>
                <dd class="col-sm-9">
                    @entry.StartDate.ToString("MMM yyyy") &ndash;
                    @(IsCurrent[i] ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                </dd>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <dt class="col-sm-3">Description</dt>
                    <dd class="col-sm-9" style="white-space: pre-line;">@entry.Description</dd>
                }
            </dl>
        }
    </div>
</div>

<!-- References -->
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>References</strong>
        <a href="javascript:void(0)" @onclick='() => OnEditSection.InvokeAsync(3)'>Edit</a>
    </div>
    <div class="card-body">
        @for (int i = 0; i < References.Count; i++)
        {
            var r = References[i];
            if (i > 0)
            {
                <hr />
            }
            <dl class="row mb-0">
                <dt class="col-sm-3">Name</dt>
                <dd class="col-sm-9">@r.Name</dd>
                @if (!string.IsNullOrWhiteSpace(r.Relationship))
                {
                    <dt class="col-sm-3">Relationship</dt>
                    <dd class="col-sm-9">@r.Relationship</dd>
                }
                <dt class="col-sm-3">Email</dt>
                <dd class="col-sm-9">@r.Email</dd>
                @if (!string.IsNullOrWhiteSpace(r.Phone))
                {
                    <dt class="col-sm-3">Phone</dt>
                    <dd class="col-sm-9">@r.Phone</dd>
                }
            </dl>
        }
    </div>
</div>

<!-- Cover Letter -->
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Cover Letter</strong>
        <a href="javascript:void(0)" @onclick='() => OnEditSection.InvokeAsync(4)'>Edit</a>
    </div>
    <div class="card-body">
        <p style="white-space: pre-line;">@CoverLetter</p>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public List<WorkEntryModel> WorkEntries { get; set; } = new();
    [Parameter] public List<bool> IsCurrent { get; set; } = new();
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public string? SubmitError { get; set; }
}

